Here's a Python program that meets your requirements. This program uses a dictionary to store the contacts and allows users to add, remove, and search for contacts.

```python
# Initialize the phonebook dictionary
phonebook = {}

def add_contact(name, number):
    """Add a contact to the phonebook."""
    if name in phonebook:
        print(f"{name} is already in the phonebook.")
    else:
        phonebook[name] = number
        print(f"{name} added to the phonebook.")

def remove_contact(name):
    """Remove a contact from the phonebook."""
    if name in phonebook:
        del phonebook[name]
        print(f"{name} removed from the phonebook.")
    else:
        print(f"Contact not found: {name}")

def search_contact(name):
    """Search for a contact in the phonebook."""
    if name in phonebook:
        print(f"{name}: {phonebook[name]}")
    else:
        print(f"Contact not found: {name}")

# Get user input
user_input = input("Enter a command (add, remove, search, or exit): ").lower()

while user_input != "exit":
    if user_input == "add":
        name = input("Enter the name: ")
        number = input("Enter the phone number: ")
        add_contact(name, number)
    elif user_input == "remove":
        name = input("Enter the name: ")
        remove_contact(name)
    elif user_input == "search":
        name = input("Enter the name: ")
        search_contact(name)
    else:
        print("Invalid command. Please try again.")

    user_input = input("Enter a command (add, remove, search, or exit): ").lower()

print("Goodbye!")
```

This program will continue to run until the user enters "exit" as the command. Each time the user enters a command, the corresponding function is called to perform the requested action.
